        "The Treasury rate adapter is currently dormant. Bind the openconnector source \"treasury-rates\" (ECB SDMX) and override TreasuryRateAdapterInterface in Application::register() to start ingesting real rates. Manual rate entries are unaffected.": "De Treasury rate-adapter is momenteel slapend. Koppel de openconnector-bron \"treasury-rates\" (ECB SDMX) en override TreasuryRateAdapterInterface in Application::register() om echte koersen te gaan verwerken. Handmatige koersinvoer blijft ongewijzigd.",
        "The booking service is temporarily unavailable. Please try again later.": "De boekingsdienst is tijdelijk niet beschikbaar. Probeer het later opnieuw.",
        "The cron has not produced a successful run yet.": "De cronjob heeft nog geen succesvolle run opgeleverd.",
        "The grid below is the declarative FxRate index. Use the filters to narrow by currency pair or source.": "Onderstaand overzicht is de declaratieve FxRate-index. Gebruik de filters om te filteren op valutapaar of bron.",
        "The payment run cannot be approved: the approving user could not be identified. Sign in and retry; an unidentified approver is blocked (fail-closed).": "De betaalbatch kan niet worden goedgekeurd: de goedkeurende gebruiker kon niet worden vastgesteld. Log in en probeer opnieuw; een niet-geïdentificeerde goedkeurder wordt geblokkeerd (fail-closed).",
        "The payment run cannot be approved: the batch could not be identified for the segregation-of-duties check (fail-closed).": "De betaalbatch kan niet worden goedgekeurd: de batch kon niet worden geïdentificeerd voor de functiescheidingscontrole (fail-closed).",
        "The payment run cannot be approved: the preparer could not be determined from the audit trail, so the four-eyes check cannot be satisfied (fail-closed).": "De betaalbatch kan niet worden goedgekeurd: de voorbereider kon niet worden bepaald op basis van het audittrail, waardoor de vierogencontrole niet kan worden uitgevoerd (fail-closed).",
        "The product master holds no products yet.": "De productmaster bevat nog geen producten.",
        "The product master is unavailable, so the rows below are shillinq’s local cache: the products its own stock and barcode records reference. Names, categories and prices are owned elsewhere and are shown blank rather than guessed.": "De productmaster is niet beschikbaar, dus tonen de onderstaande rijen shillinq's lokale cache: de producten waarnaar de eigen voorraad- en barcoderegistraties verwijzen. Namen, categorieën en prijzen zijn elders eigendom en worden leeg getoond in plaats van geraden.",
        "The product master is unavailable, so the rows below are the attribute surface the integration contract publishes. The “Owned By” column says which application authors each value.": "De productmaster is niet beschikbaar, dus tonen de onderstaande rijen het attributenoppervlak dat het integratiecontract publiceert. De kolom \"Eigenaar\" geeft aan welke applicatie elke waarde vastlegt.",
        "The proposed booking overlaps existing bookings:": "De voorgestelde boeking overlapt met bestaande boekingen:",
        "The token is stored in the Nextcloud secrets store and never returned to the browser.": "Het token wordt opgeslagen in de Nextcloud-secrets-store en wordt nooit teruggestuurd naar de browser.",
        "Third-Party Subsidy (Cents)": "Subsidie Van Derden Cents",
        "This adapter is dormant. The surrounding lifecycle advances safely — submissions are recorded in the structured log but never sent to a third party — until the activation steps above are completed.": "Deze adapter is slapend. De omringende lifecycle gaat veilig verder — indieningen worden vastgelegd in het gestructureerde log maar worden nooit verzonden naar een derde partij — totdat de activatiestappen hierboven zijn uitgevoerd.",
        "This adapter is live. Submissions are sent to the configured third party. Audit oc_jobs + the relevant register lifecycle for delivery confirmations.": "Deze adapter is live. Indieningen worden verzonden naar de geconfigureerde derde partij. Controleer oc_jobs + de relevante registerlifecycle voor leveringsbevestigingen.",
        "This app needs OpenRegister to store and manage data. Please install OpenRegister from the app store to get started.": "Deze app heeft OpenRegister nodig om gegevens op te slaan en te beheren. Installeer OpenRegister via de app store om te beginnen.",
        "This appointment has already been confirmed.": "Deze afspraak is al bevestigd.",
        "This booking has already been invoiced.": "Deze boeking is al gefactureerd.",
        "This confirmation link has expired. Please request a new one.": "Deze bevestigingslink is verlopen. Vraag een nieuwe aan.",
        "This confirmation link is incomplete.": "Deze bevestigingslink is onvolledig.",
        "This confirmation link is missing required information.": "Deze bevestigingslink mist verplichte informatie.",
        "This confirmation link is no longer valid; a newer one was sent.": "Deze bevestigingslink is niet meer geldig; er is een nieuwe verstuurd.",
        "This confirmation link is not valid.": "Deze bevestigingslink is niet geldig.",
        "This deadline is coming up. Open Shillinq to review it.": "Deze deadline komt eraan. Open Shillinq om deze te bekijken.",
        "This invoice number already exists for this supplier": "Dit factuurnummer bestaat al voor deze leverancier",
        "This payment run cannot be exported: at least one invoice in the batch has already been paid. Remove the settled invoice before exporting; paying it again would be a duplicate payment.": "Deze betaalbatch kan niet worden geëxporteerd: minstens één factuur in de batch is al betaald. Verwijder de reeds betaalde factuur voordat u exporteert; nogmaals betalen zou een dubbele betaling zijn.",
        "This payment run cannot be exported: at least one invoice in the batch is already queued in another open or executed payment batch. Remove the duplicate line before exporting to prevent a double payment.": "Deze betaalbatch kan niet worden geëxporteerd: minstens één factuur in de batch staat al in een andere openstaande of uitgevoerde betaalbatch. Verwijder de dubbele regel voordat u exporteert om een dubbele betaling te voorkomen.",
        "This payment run cannot be exported: the batch could not be identified for the duplicate-payment check (fail-closed).": "Deze betaalbatch kan niet worden geëxporteerd: de batch kon niet worden geïdentificeerd voor de dubbele-betalingscontrole (fail-closed).",
        "This payment run cannot be exported: the duplicate-payment check could not be completed, so the disbursement is blocked (fail-closed).": "Deze betaalbatch kan niet worden geëxporteerd: de dubbele-betalingscontrole kon niet worden voltooid, dus de uitbetaling is geblokkeerd (fail-closed).",
        "This rule would match {count} of {total} unmatched transactions": "Deze regel zou {count} van {total} niet-gematchte transacties matchen",
