        "GmbH": "GmbH",
        "Verein": "Verein",
        "Einzelunternehmen": "Einzelunternehmen",
        "A chart of accounts (RGS, Referentie GrootboekSchema) is the standardised layout of ledger accounts your balance sheet and profit-and-loss statement are based on. Based on your organisation type, a matching template is already suggested. You can adjust it.": "Een rekeningschema (RGS, Referentie GrootboekSchema) is de gestandaardiseerde indeling van grootboekrekeningen waarop je balans en winst-en-verliesrekening zijn gebaseerd. Op basis van je organisatietype is al een passend sjabloon voorgesteld. Je kunt dat aanpassen.",
        "Load the chosen chart of accounts (ledger accounts), the VAT rates, and, for government bodies, the BBV task fields into the administration. This may take a while. Click \"Run\" to start.": "Laad het gekozen rekeningschema (grootboekrekeningen), de btw-tarieven en, voor overheidsorganisaties, de BBV-taakvelden in de administratie. Dit kan even duren. Klik op \"Uitvoeren\" om te starten.",
        "Getting started": "Aan de slag",
        "Let's take a quick spin through your bookkeeping. We'll create a sales invoice together so you can see how the pieces fit, and you'll add the record yourself.": "Laten we snel door je boekhouding lopen. We maken samen een verkoopfactuur zodat je ziet hoe alles in elkaar grijpt, en jij legt het record zelf vast.",
        "The quickest way to bill a customer is the quick draft. Click Create invoice on the dashboard to open it.": "De snelste manier om een klant te factureren is het snelconcept. Klik op Factuur maken op het dashboard om het te openen.",
        "Click Create invoice": "Klik op Factuur maken",
        "In the quick draft: search for and pick a customer, add a line (description, quantity, unit price and VAT rate), then Save draft. Shillinq numbers the invoice and books it to Accounts Receivable for you.": "In het snelconcept: zoek en kies een klant, voeg een regel toe (omschrijving, aantal, stuksprijs en btw-tarief) en klik op Concept opslaan. Shillinq nummert de factuur en boekt die voor je op Debiteuren.",
        "Fill the quick draft and Save draft": "Vul het snelconcept in en sla het concept op",
        "Your first invoice is on the books": "Je eerste factuur staat in de boeken",
        "The Dashboard tracks your finances as invoices come and go. The documentation covers the rest.": "Het dashboard volgt je financiën terwijl facturen komen en gaan. De documentatie behandelt de rest.",
        "Open the documentation to keep going": "Open de documentatie om verder te gaan",
