        "Change actor": "Wijziger",
        "Before/after diff": "Verschil voor en na",
        "Inclusive start date (YYYY-MM-DD) for the export window.": "Startdatum van de exportperiode (JJJJ-MM-DD), inclusief deze dag.",
        "Inclusive end date (YYYY-MM-DD) for the export window.": "Einddatum van de exportperiode (JJJJ-MM-DD), inclusief deze dag.",
        "Export file format.": "Bestandsformaat van de export.",
        "Scope": "Reikwijdte",
        "all = every audit event in window; subject = events where caller is the actor (GDPR article 15 subject access).": "alles = elke auditgebeurtenis in de periode; betrokkene = gebeurtenissen waarbij de aanvrager zelf de actor is (inzagerecht, AVG artikel 15).",
        "Export compliance data as CSV, XLSX or JSON. Only the auditor group can use this. Personal data such as names, addresses, contact details and identification numbers is removed before the file is written, and every export is itself recorded in the audit trail.": "Exporteer compliancegegevens als CSV, XLSX of JSON. Alleen de accountantsgroep kan dit gebruiken. Persoonsgegevens zoals namen, adressen, contactgegevens en identificatienummers worden verwijderd voordat het bestand wordt weggeschreven, en elke export wordt zelf vastgelegd in de audittrail.",
        "Activity": "Activiteit",
        "Detail": "Detail",
        "Approval / signing / decision activity for financial documents, sourced from the OpenRegister audit trail (the same store the Audit trail and Change history pages read). Scoped to the approval-and-decision object types (ApprovalRequest / ApprovalTask / SigningAuthority lifecycle plus the documents they gate). Replaces the earlier Nextcloud Activity-app integration, whose legacy /apps/activity/activity/list endpoint was removed in Activity 7.x (returned 404); the OCS Activity API cannot be consumed by the logs widget (it requires the OCS-APIRequest header and wraps rows in ocs.data).": "Goedkeurings-, onderteken- en besluitactiviteit op financiële documenten, afkomstig uit het audittrail van OpenRegister. Beperkt tot goedkeurings- en besluitobjecten en de documenten waarvoor zij als poort dienen.",
