        "Open any stock line to see the moves behind its current balance, in date order, with a running total that adds up to the quantity on hand.": "Open een voorraadregel om de mutaties achter het huidige saldo te zien, op datum, met een doorlopend totaal dat uitkomt op het aanwezige aantal.",
