        "Counts in result": "Telt mee in resultaat",
        "The amount with its sign: positive on the credit side, negative on the debit side. Calculated when the line is saved, so the sum of a segment's lines is its result.": "Het bedrag met teken: positief aan de creditzijde, negatief aan de debetzijde. Berekend bij het opslaan van de regel, zodat de som van de regels van een segment het resultaat is.",
        "Whether the line's account is a profit and loss account (revenue or expenses) or a balance sheet account, as the chart of accounts said when the transaction was posted.": "Of de rekening van de regel een resultatenrekening (opbrengsten of kosten) of een balansrekening is, zoals het rekeningschema zei toen de boeking werd geboekt.",
        "True while the line's transaction is posted and not reversed. A draft line, and the lines of a reversed transaction and of its reversal, do not count.": "Waar zolang de boeking van de regel geboekt is en niet is teruggedraaid. Een conceptregel, en de regels van een teruggedraaide boeking en van de terugdraaiing, tellen niet mee.",
