        "The project owner was warned that this assignment reached 100 percent of its hours. Cleared when the estimate changes.": "De projecteigenaar is gewaarschuwd dat deze toewijzing 100 procent van de uren heeft bereikt. Vervalt als de raming wijzigt.",
        "Nextcloud user id of the project owner (the project's responsible user), who receives the hours warnings.": "Nextcloud-gebruikersnaam van de projecteigenaar (de verantwoordelijke van het project), die de urenwaarschuwingen krijgt.",
