        "New useful life (months)": "Nieuwe gebruiksduur (maanden)",
        "On disposal, credit the gain to the reinvestment reserve account instead of profit, and keep it as a reserve for a replacement.": "Boek bij verkoop de winst op de rekening herinvesteringsreserve in plaats van in de winst, en bewaar die als reserve voor een vervanger.",
