        "Sold asset number": "Nummer verkocht bezit",
        "The acquisition cost less the reinvestment reserves applied to it; fiscal depreciation starts from this amount.": "De aanschafwaarde min de herinvesteringsreserves die erop zijn toegepast; de fiscale afschrijving gaat uit van dit bedrag.",
        "The amount less what was applied.": "Het bedrag min wat is toegepast.",
        "The asset whose disposal gain formed the reserve.": "Het bezit waarvan de boekwinst de reserve vormde.",
        "The date the extra depreciation is booked on.": "De datum waarop de extra afschrijving wordt geboekt.",
        "The disposal date.": "De verkoopdatum.",
        "The end of the third year after the year the reserve was formed. An unused remainder is released to profit then.": "Het einde van het derde jaar na het jaar waarin de reserve is gevormd. Een ongebruikt restant valt dan vrij in de winst.",
        "The equity account the reserve is kept on.": "De vermogensrekening waarop de reserve staat.",
        "The first day the new method or life applies. Months already posted from this date block the revision.": "De eerste dag waarop de nieuwe methode of gebruiksduur geldt. Maanden vanaf deze datum die al geboekt zijn, blokkeren de herziening.",
        "The gain added to the reserve.": "De boekwinst die aan de reserve is toegevoegd.",
        "The journal entry that released the remainder to profit.": "De journaalpost waarmee het restant in de winst is vrijgevallen.",
        "The method from the revision date on. Leave empty to keep the current method.": "De methode vanaf de herzieningsdatum. Laat leeg om de huidige methode te houden.",
        "The open reinvestment reserve to apply to this asset.": "De open herinvesteringsreserve die op dit bezit wordt toegepast.",
        "The part applied to replacement assets.": "Het deel dat op vervangende bezittingen is toegepast.",
        "The part of the reserve applied to this asset. Leave empty to apply what is left of it, up to the asset's cost.": "Het deel van de reserve dat op dit bezit wordt toegepast. Laat leeg om toe te passen wat ervan over is, tot de aanschafwaarde.",
        "The sold asset's number, kept for the overview.": "Het nummer van het verkochte bezit, bewaard voor het overzicht.",
        "The total useful life in months from acquisition, after the revision. Leave empty to keep the current life.": "De totale gebruiksduur in maanden vanaf aanschaf, na de herziening. Laat leeg om de huidige gebruiksduur te houden.",
        "Why the asset loses value at once.": "Waarom het bezit in een keer waarde verliest.",
        "Why the line was planned again or booked extra.": "Waarom de regel opnieuw is gepland of extra is geboekt.",
        "Why the method or useful life changes. Kept on the new schedule lines.": "Waarom de methode of gebruiksduur verandert. Staat op de nieuwe regels van het schema.",
        "fixed-amount for a planned month, extra for a one-off extra depreciation.": "fixed-amount voor een geplande maand, extra voor een eenmalige extra afschrijving.",
        "open: still available; applied: fully applied; released: the remainder went to profit at expiry.": "open: nog beschikbaar; applied: volledig toegepast; released: het restant viel op de vervaldatum vrij in de winst.",
        "planned: not yet in the ledger; posted: in the ledger through the journal entry in glTransactionRef.": "planned: nog niet in het grootboek; posted: in het grootboek via de journaalpost in glTransactionRef.",
        "The gain on a sold asset kept for a replacement (art. 3.54 Wet IB 2001), applied to the replacement's fiscal cost or released to profit when its term ends.": "De boekwinst op een verkocht bezit, bewaard voor een vervanger (art. 3.54 Wet IB 2001), toegepast op de fiscale aanschafwaarde van de vervanger of vrijgevallen in de winst als de termijn afloopt.",
        "Revise depreciation": "Afschrijving herzien",
        "Change the method or useful life from a date. The unposted months from then on are planned again from the book value on that date; posted months stay as they are.": "Wijzig de methode of gebruiksduur vanaf een datum. De niet-geboekte maanden vanaf dan worden opnieuw gepland vanuit de boekwaarde op die datum; geboekte maanden blijven zoals ze zijn.",
        "Extra depreciation": "Extra afschrijving",
        "Book a one-off depreciation at once, then plan the remaining months from the lower book value.": "Boek direct een eenmalige afschrijving en plan daarna de resterende maanden vanuit de lagere boekwaarde.",
